static void	print_special_operator_parser(t_redir *current_redir)
{
	while (current_redir != NULL)
	{
		if (current_redir->type == 4)
			ft_printf("%s", PARSER_REDIR_IN);
		else if (current_redir->type == 5)
			ft_printf("%s", PARSER_REDIR_OUT);
