	shell_lvl_node = malloc(sizeof(t_env));
	if (shell_lvl_node == NULL)
		return (print_err_false(ERR_MALLOC));
	if (fill_shlvl_node(data, shell_lvl_node) == false)
	{
		free(shell_lvl_node);
		return (false);
	}
	history_node = malloc(sizeof(t_env));
	if (history_node == NULL)
		return (print_err_false(ERR_MALLOC));
