	size_t	i;
	t_cmd	*current;

	index = 0;
	i = 0;
	current = cmd;
	while (current != NULL)
	{
		if (need_split_expand(cmd, current->params) == true)
		{
			current->params = split_expand(data, current->params, index, i);
			if (current->params == NULL)
				return (print_err_false(ERR_MALLOC));
		}
		current = current->next;
	}
	return (true);
}

